/** The minimal shape `findUnknownGuardNames` needs from a fire-log record. */
export interface GuardNameBearingEntry {
  guardName: string;
  timestamp: string;
}

/** One unresolved `guardName`, with enough context to triage it without re-reading the log. */
export interface UnknownGuardName {
  guardName: string;
  count: number;
  firstSeen: string;
  lastSeen: string;
  /** True when the name is in `RETIRED_GUARD_NAMES` but has produced records AFTER its recorded `lastSeen`. */
  retiredButRecent: boolean;
  /** True when the name is a declared `FIXTURE_GUARD_NAMES` entry — a known incident, not a fresh unknown. */
  knownFixture: boolean;
}

export interface ResolveKnownGuardNamesInput {
  /** `GUARD_REGISTRY.map(r => r.name)` — passed in rather than imported so this module stays a leaf. */
  registryNames: readonly string[];
  /** Derived from `src/hooks/pre-commit.ts` when available; falls back to `PRECOMMIT_STEP_NAMES`. */
  precommitNames?: readonly string[];
}

/**
 * The set of `guardName` values that correspond to a real, current enforcement
 * point. Deliberately EXCLUDES retired and fixture names — those are
 * classified separately by `findUnknownGuardNames` so each gets its own
 * report line rather than being silently folded into "known".
 */
export function resolveKnownGuardNames(input: ResolveKnownGuardNamesInput): ReadonlySet<string> {
  return new Set([
    ...input.registryNames,
    ...(input.precommitNames ?? PRECOMMIT_STEP_NAMES),
    ...STANDALONE_GUARD_NAMES,
  ]);
}

/**
 * Every `guardName` in `entries` that does not resolve to a current
 * enforcement point, aggregated with its record count and time span.
 *
 * Retired and fixture names are RETURNED, not filtered out — with
 * `retiredButRecent` / `knownFixture` set so the caller can render each class
 * differently and decide which ones are actually actionable. Filtering them
 * here would make a retired name that suddenly resumes firing invisible, which
 * is precisely the case worth catching.
 */
export function findUnknownGuardNames(
  entries: readonly GuardNameBearingEntry[],
  known: ReadonlySet<string>
): UnknownGuardName[] {
  const byName = new Map<string, { count: number; first: string; last: string }>();

  for (const entry of entries) {
    if (known.has(entry.guardName)) continue;
    const existing = byName.get(entry.guardName);
    if (!existing) {
      byName.set(entry.guardName, { count: 1, first: entry.timestamp, last: entry.timestamp });
      continue;
    }
    existing.count += 1;
    if (entry.timestamp < existing.first) existing.first = entry.timestamp;
    if (entry.timestamp > existing.last) existing.last = entry.timestamp;
  }

  const results: UnknownGuardName[] = [];
  for (const [guardName, agg] of byName) {
    const retired = RETIRED_GUARD_NAMES.get(guardName);
    results.push({
      guardName,
      count: agg.count,
      firstSeen: agg.first,
      lastSeen: agg.last,
      // Compare DATE prefixes: `lastSeen` in the retired map is a bare date,
      // while a record timestamp is a full ISO instant, so a raw string
      // compare would report every same-day record as "after".
      retiredButRecent: retired !== undefined && agg.last.slice(0, 10) > retired.lastSeen,
      knownFixture: FIXTURE_GUARD_NAMES.has(guardName),
    });
  }

  return results.sort((a, b) => b.count - a.count || a.guardName.localeCompare(b.guardName));
}

/**
 * Whether an audit result should FAIL the check.
 *
 * A declared fixture name is expected until its records are removed, and a
 * retired name firing only within its recorded window is history. Anything
 * else — a genuinely unrecognized name, or a retired name that resumed — is a
 * failure.
 */
export function hasActionableUnknowns(unknowns: readonly UnknownGuardName[]): boolean {
  return unknowns.some((u) => u.retiredButRecent || (!u.knownFixture && !isRetired(u.guardName)));
}

function isRetired(guardName: string): boolean {
  return RETIRED_GUARD_NAMES.has(guardName);
}
